// Free text typed by members. Fields picked from fixed option lists are left out
// on purpose: those values are interface copy and should still be translated.
function memberTexts(){
  const texts=new Set();
  const add=(item,...keys)=>{for(const key of keys){const v=item?.[key];if(typeof v==='string'&&v.trim())texts.add(v.trim())}};
  const demoSessions=[1,2,3,4,-101,-102];
  const archives=[state,...(state.agendaArchives||[])];
  for(const agenda of archives){
    (agenda.sessions||[]).forEach(s=>{if(!demoSessions.includes(s.id))add(s,'title','place','summary','notes','coach','gear','guide')});
    (agenda.competition||[]).forEach(c=>add(c,'name','place'));
    (agenda.comments||[]).forEach(c=>add(c,'text'));
    (agenda.videos||[]).forEach(v=>add(v,'title'));
    (agenda.exercises||[]).forEach(e=>add(e,'title','sets','notes'));
  }
  const profiles=[state.profile,...Object.values(state.accessProfiles||{})];
  const records=[{goals:state.goals,reviews:state.reviews},...Object.values(state.athletes||{})];
  records.forEach(r=>{
    if(r.profile)profiles.push(r.profile);
    (r.goals||[]).forEach(g=>add(g,'title','detail'));
    Object.values(r.reviews||{}).forEach(n=>add(n,'good','focus'));
  });
  profiles.forEach(p=>{
    add(p,'name','firstName','lastName','academy','goal','racket','preferences');
    add(p?.baseline,'strengths','priority');
    Object.values(p?.monthlyReviews||{}).forEach(n=>add(n,'good','focus','goal'));
  });
  (state.directory||[]).forEach(m=>add(m,'name','academy','bio','email','phone'));
  (state.academyGroups||[]).forEach(g=>{add(g,'academy','address');(g.posts||[]).forEach(p=>add(p,'title','text'))});
  (state.privateLessons||[]).forEach(b=>(b.students||[]).forEach(s=>add(s,'name')));
  add(state,'coachNote');
  return texts;
}
// Sentences with numbers or names inside: matched by shape, so the dictionary above stays exact-match only.
const dashboardUnits={'por día':['per day','par jour'],'por semana':['per week','par semaine'],'por mes':['per month','par mois'],'por trimestre':['per quarter','par trimestre'],'por año':['per year','par an']};
const dashboardViews={diario:['daily','quotidienne'],semanal:['weekly','hebdomadaire'],mensual:['monthly','mensuelle'],trimestral:['quarterly','trimestrielle'],anual:['yearly','annuelle']};
const dashboardMoods={'sin energía':['no energy','sans énergie'],'con cansancio':['tired','fatigué'],normal:['normal','normal'],bien:['good','bien'],excelente:['excellent','excellent']};
const dashboardS=(n,one,many)=>Number(n)===1?one:many;
const dashboardPatterns=[
  [/^Subió (\d+) puntos? respecto al periodo anterior\.$/,(m,i)=>i?`En hausse de ${m[1]} point${dashboardS(m[1],'','s')} par rapport à la période précédente.`:`Up ${m[1]} point${dashboardS(m[1],'','s')} from the previous period.`],
  [/^Bajó (\d+) puntos? respecto al periodo anterior\.$/,(m,i)=>i?`En baisse de ${m[1]} point${dashboardS(m[1],'','s')} par rapport à la période précédente.`:`Down ${m[1]} point${dashboardS(m[1],'','s')} from the previous period.`],
  [/^Van en sintonía: (tu sensación y la de tu coach|jugador y coach) difieren (\d+) puntos? en promedio\.$/,(m,i)=>{const own=m[1]!=='jugador y coach';return i?`En phase : ${own?'votre ressenti et celui de votre coach':'le joueur et le coach'} diffèrent de ${m[2]} point${dashboardS(m[2],'','s')} en moyenne.`:`In sync: ${own?'your feeling and your coach’s':'player and coach'} differ by ${m[2]} point${dashboardS(m[2],'','s')} on average.`}],
  [/^Te ves (\d+) puntos? más arriba que tu coach\. Vale la pena platicarlo\.$/,(m,i)=>i?`Vous vous voyez ${m[1]} point${dashboardS(m[1],'','s')} au-dessus de votre coach. Cela vaut la peine d’en discuter.`:`You rate yourself ${m[1]} point${dashboardS(m[1],'','s')} higher than your coach does. Worth talking about.`],
  [/^La sensación del jugador está (\d+) puntos? arriba del coach\. Vale la pena platicarlo\.$/,(m,i)=>i?`Le ressenti du joueur est ${m[1]} point${dashboardS(m[1],'','s')} au-dessus de celui du coach. Cela vaut la peine d’en discuter.`:`The player’s feeling is ${m[1]} point${dashboardS(m[1],'','s')} above the coach’s. Worth talking about.`],
  [/^Tu coach te ve (\d+) puntos? más arriba de lo que tú te sientes\. Vas mejor de lo que crees\.$/,(m,i)=>i?`Votre coach vous voit ${m[1]} point${dashboardS(m[1],'','s')} au-dessus de ce que vous ressentez. Vous allez mieux que vous ne le pensez.`:`Your coach sees you ${m[1]} point${dashboardS(m[1],'','s')} higher than you feel. You are doing better than you think.`],
  [/^La evaluación del coach está (\d+) puntos? arriba de la sensación del jugador\.$/,(m,i)=>i?`L’évaluation du coach est ${m[1]} point${dashboardS(m[1],'','s')} au-dessus du ressenti du joueur.`:`The coach’s assessment is ${m[1]} point${dashboardS(m[1],'','s')} above the player’s feeling.`],
  [/^Llevas (\d+) días? de datos\. La vista (\S+) se abre en (\d+) días?\. Mientras, responde tu encuesta cada día\.$/,(m,i)=>{const view=(dashboardViews[m[2]]||[m[2],m[2]])[i];return i?`Vous avez ${m[1]} jour${dashboardS(m[1],'','s')} de données. La vue ${view} s’ouvre dans ${m[3]} jour${dashboardS(m[3],'','s')}. En attendant, répondez à votre enquête chaque jour.`:`You have ${m[1]} day${dashboardS(m[1],'','s')} of data. The ${view} view opens in ${m[3]} day${dashboardS(m[3],'','s')}. Meanwhile, answer your survey every day.`}],
  [/^¿Cómo va (.+)\?$/,(m,i)=>i?`Comment va ${m[1]} ?`:`How is ${m[1]} doing?`],
  [/^Cómo se siente (.+)$/,(m,i)=>i?`Comment se sent ${m[1]}`:`How ${m[1]} feels`],
  [/^(Tu|Su) respuesta después de cada entrenamiento, (por \S+)\.$/,(m,i)=>{const unit=(dashboardUnits[m[2]]||[m[2],m[2]])[i];return i?`${m[1]==='Tu'?'Votre':'Sa'} réponse après chaque entraînement, ${unit}.`:`${m[1]==='Tu'?'Your':'Their'} answer after each training session, ${unit}.`}],
  [/^Lo que el coach anota después de cada entrenamiento, (por \S+)\.$/,(m,i)=>{const unit=(dashboardUnits[m[1]]||[m[1],m[1]])[i];return i?`Ce que le coach note après chaque entraînement, ${unit}.`:`What the coach notes after each training session, ${unit}.`}],
  [/^Semana del (.+)$/,(m,i)=>i?`Semaine du ${m[1]}`:`Week of ${m[1]}`],
  [/^Trimestre (\d) de (\d{4})$/,(m,i)=>i?`Trimestre ${m[1]} de ${m[2]}`:`Quarter ${m[1]} of ${m[2]}`],
  [/^Año (\d{4})$/,(m,i)=>i?`Année ${m[1]}`:`Year ${m[1]}`],
  [/^Gráfica (\d)$/,(m,i)=>i?`Graphique ${m[1]}`:`Chart ${m[1]}`],
  [/^(· )?(\d+) encuestas?$/,(m,i)=>`${m[1]||''}${m[2]} ${i?'enquête'+dashboardS(m[2],'','s'):'survey'+dashboardS(m[2],'','s')}`],
  [/^(· )?(\d+) evaluaciones?$/,(m,i)=>`${m[1]||''}${m[2]} ${i?'évaluation'+dashboardS(m[2],'','s'):'assessment'+dashboardS(m[2],'','s')}`],
  [/^ánimo: (.+)$/,(m,i)=>`${i?'moral : ':'mood: '}${(dashboardMoods[m[1]]||[m[1],m[1]])[i]}`],
  [/^lo que faltó: ([\s\S]+)$/,(m,i)=>i?`ce qui a manqué : ${m[1]}`:`what was missing: ${m[1]}`],
  [/^lo que falta: ([\s\S]+)$/,(m,i)=>i?`ce qui manque : ${m[1]}`:`what is missing: ${m[1]}`],
  [/^(\d+) jugadores?$/,(m,i)=>i?`${m[1]} joueur${dashboardS(m[1],'','s')}`:`${m[1]} player${dashboardS(m[1],'','s')}`],
  [/^Último respaldo en este dispositivo: (.+)\.$/,(m,i)=>i?`Dernière sauvegarde sur cet appareil : ${m[1]}.`:`Last backup on this device: ${m[1]}.`]
];
function dashboardText(text,mine=new Set()){
  if(coverLanguage==='es'||mine.has(text.trim()))return text;
  const index=coverLanguage==='fr'?1:0;
  function label(part){
    const clean=part.trim();
    if(mine.has(clean))return part;
    const value=dashboardLabels.get(clean)?.[index];
    if(value)return part.replace(clean,value);
    for(const [pattern,build] of dashboardPatterns){const found=clean.match(pattern);if(found)return part.replace(clean,()=>build(found,index))}
    const rain=clean.match(/^Se cancela el entrenamiento de tenis de la mañana(?: de las (\d\d:\d\d))?\. Solo habrá preparación física en el gimnasio\.$/);
    if(rain)return index?`L’entraînement de tennis du matin${rain[1]?' de '+rain[1]:''} est annulé. Seule la préparation physique en salle est maintenue.`:`Morning tennis${rain[1]?' at '+rain[1]:''} is cancelled. Only fitness training in the gym will take place.`;
    if(clean.startsWith('Seguimiento de '))return (index?'Suivi de ':'Progress for ')+clean.slice(15);
    return part.replace(/Cancha (\d+)/g,index?'Court $1':'Court $1');
  }
  const exact=dashboardLabels.get(text.trim());
  return exact?text.replace(text.trim(),exact[index]):text.split(/( · | \/ )/).map(label).join('');
}
function translateDashboard(){
  if(coverLanguage==='es')return;
  const shell=document.querySelector('.shell');
  const mine=memberTexts();
  const walk=document.createTreeWalker(shell,NodeFilter.SHOW_TEXT);
  while(walk.nextNode()){
    const node=walk.currentNode;
    if(node.parentElement.closest('select,textarea,footer,svg'))continue;
    const next=dashboardText(node.data,mine);
    if(next!==node.data)node.data=next;
  }
  shell.querySelectorAll('[aria-label]').forEach(el=>{
    const original=el.getAttribute('aria-label');
    const next=dashboardText(original,mine);if(next!==original)el.setAttribute('aria-label',next);
  });
}
